from taskapp.constants import DEFAULT_PAGE_SIZE, DEFAULT_PRIORITY, HTTP_CREATED, HTTP_OK
from taskapp.services import tasks as task_service
from taskapp.services.pagination import paginate
from taskapp.utils.ids import parse_id
from taskapp.utils.querystring import parse_page_params


def list_tasks(store, request, project_id):
    page, size = parse_page_params(request.query, default_size=DEFAULT_PAGE_SIZE)
    items = task_service.tasks_for_project(store, parse_id(project_id, field="project_id"))
    return HTTP_OK, paginate(items, page=page, page_size=size)


def create_task(store, request, project_id):
    task = task_service.create_task(
        store,
        parse_id(project_id, field="project_id"),
        request.body.get("title"),
        priority=request.body.get("priority", DEFAULT_PRIORITY),
    )
    return HTTP_CREATED, task


def search_tasks(store, request):
    page, size = parse_page_params(request.query, default_size=DEFAULT_PAGE_SIZE)
    return HTTP_OK, task_service.search_tasks(store, request.query.get("q", ""), page=page, page_size=size)


def update_task(store, request, task_id):
    return HTTP_OK, task_service.update_task(store, parse_id(task_id, field="task_id"), request.body)

"""Task use cases."""

from taskapp.constants import DEFAULT_PAGE_SIZE, DEFAULT_PRIORITY
from taskapp.errors import ConflictError, NotFoundError
from taskapp.models_generated import Task
from taskapp.services.pagination import Page, paginate
from taskapp.services.projects import get_project_or_404
from taskapp.services.validation import validate_priority, validate_status, validate_title
from taskapp.storage.repository import get_repo


def get_task_or_404(store, task_id: int) -> Task:
    task = get_repo(store, "tasks").get(task_id)
    if task is None:
        raise NotFoundError(f"task {task_id} not found", code="TASK_NOT_FOUND")
    return task


def tasks_for_project(store, project_id: int) -> list[Task]:
    get_project_or_404(store, project_id)
    return [task for task in get_repo(store, "tasks").all() if task.project_id == project_id]


def create_task(store, project_id: int, title, priority=DEFAULT_PRIORITY) -> Task:
    project = get_project_or_404(store, project_id)
    if project.archived:
        raise ConflictError("project is archived", code="PROJECT_ARCHIVED")
    clean_title = validate_title(title)
    clean_priority = validate_priority(priority)
    return get_repo(store, "tasks").add(
        lambda i: Task(id=i, project_id=project_id, title=clean_title, priority=clean_priority)
    )


def update_task(store, task_id: int, changes: dict) -> Task:
    task = get_task_or_404(store, task_id)
    if "title" in changes:
        task.title = validate_title(changes["title"])
    if "status" in changes:
        task.status = validate_status(changes["status"])
    if "priority" in changes:
        task.priority = validate_priority(changes["priority"])
    return get_repo(store, "tasks").save(task)


def search_tasks(store, query: str, page: int = 1, page_size: int = DEFAULT_PAGE_SIZE) -> Page:
    needle = query.strip().lower()
    matches = [task for task in get_repo(store, "tasks").all() if needle in task.title.lower()]
    return paginate(matches, page=page, page_size=page_size)

"""Generate taskapp/models_generated.py from schema/models.json and refresh schema/models.lock."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SCHEMA = ROOT / "schema" / "models.json"
TARGET = ROOT / "taskapp" / "models_generated.py"
LOCK = ROOT / "schema" / "models.lock"

HEADER = (
    "# AUTO-GENERATED by scripts/gen_models.py from schema/models.json.\n"
    "# DO NOT EDIT BY HAND. Change schema/models.json and re-run the generator.\n"
)


def render(schema: dict) -> str:
    lines = [HEADER + f"# schema version: {schema['version']}", "", "from __future__ import annotations", ""]
    lines.append("from dataclasses import dataclass")
    for model in schema["models"]:
        lines += ["", "", "@dataclass", f"class {model['name']}:"]
        for field in model["fields"]:
            if "default" in field:
                lines.append(f"    {field['name']}: {field['type']} = {field['default']}")
            else:
                lines.append(f"    {field['name']}: {field['type']}")
    lines.append("")
    return "\n".join(lines)


def sha256(text: str) -> str:
    return hashlib.sha256(text.replace("\r\n", "\n").encode("utf-8")).hexdigest()


def main() -> int:
    schema = json.loads(SCHEMA.read_text(encoding="utf-8"))
    output = render(schema)
    TARGET.write_text(output, encoding="utf-8", newline="\n")
    lock = {"schema_version": schema["version"], "sha256": sha256(output)}
    LOCK.write_text(json.dumps(lock, indent=2) + "\n", encoding="utf-8", newline="\n")
    print(f"generated taskapp/models_generated.py (schema version {schema['version']})")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Schema base class: turns models, lists and pages into plain dicts."""

from __future__ import annotations

from typing import Any

from taskapp.services.pagination import Page


class Schema:
    fields: tuple[str, ...] = ()

    @classmethod
    def dump(cls, obj: Any) -> dict[str, Any]:
        if isinstance(obj, dict):
            return {name: obj[name] for name in cls.fields}
        return {name: getattr(obj, name) for name in cls.fields}

    @classmethod
    def render(cls, payload: Any) -> Any:
        if payload is None:
            return None
        if isinstance(payload, Page):
            return {
                "items": [cls.dump(item) for item in payload.items],
                "page": payload.page,
                "page_size": payload.page_size,
                "has_next": payload.has_next,
            }
        if isinstance(payload, list):
            return [cls.dump(item) for item in payload]
        return cls.dump(payload)

"""Typed access to store tables."""

from __future__ import annotations

from collections.abc import Callable
from typing import Generic, TypeVar

T = TypeVar("T")


class Repository(Generic[T]):
    def __init__(self, store, name: str) -> None:
        self._store = store
        self._name = name

    def add(self, factory: Callable[[int], T]) -> T:
        new_id = self._store.next_id(self._name)
        obj = factory(new_id)
        self._store.table(self._name)[new_id] = obj
        return obj

    def get(self, obj_id: int) -> T | None:
        return self._store.table(self._name).get(obj_id)

    def all(self) -> list[T]:
        return sorted(self._store.table(self._name).values(), key=lambda obj: obj.id)

    def save(self, obj: T) -> T:
        self._store.table(self._name)[obj.id] = obj
        return obj


def get_repo(store, name: str) -> Repository:
    return Repository(store, name)

